create temporary table b24_before(fn text primary key, fn_oid oid not null, pre_src text not null, attrs_md5 text not null) on commit drop;
create temporary table b24_cert(certified text not null) on commit drop;
create function pg_temp.b24_attrs(p_oid oid) returns text language sql stable as $f$
  select md5(concat_ws('|', p.proowner::text, coalesce(p.proacl::text, ''), p.prosecdef::text, p.proisstrict::text, p.provolatile::text,
    p.proleakproof::text, p.proparallel::text, p.prolang::text, p.procost::text, p.prorows::text, p.prorettype::text, p.proargtypes::text,
    coalesce(p.proargnames::text, ''), coalesce(p.proargmodes::text, ''), coalesce(p.proallargtypes::text, ''), coalesce(p.proconfig::text, ''),
    p.prokind::text, coalesce(obj_description(p.oid, 'pg_proc'), '')))
  from pg_proc p where p.oid = p_oid
$f$;

do $pre$
declare
  r record; v_oid oid; v_src text; v_n integer; v_certified text;
  v_strict boolean := coalesce(nullif(current_setting('b24.preimage', true), ''), 'strict') <> 'relaxed';
begin
  if (select count(*) from b24_targets) <> 54 or (select sum(sites) from b24_targets) <> 89 then
    raise exception 'B24_TARGET_TABLE_INVALID' using errcode = '55000';
  end if;
  v_certified := private.closure_source_digest_v5();
  if v_certified is distinct from (select sha256 from private.closure_source_v5 where singleton)
     or v_certified is distinct from (select sha256 from private.closure_erasure_source_v5 where singleton)
     or not private.retention_ai_source_ready() then
    raise exception 'B24_CERTIFICATE_NOT_READY' using errcode = '55000';
  end if;
  insert into b24_cert(certified) values (v_certified);
  if v_strict and exists (
       select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
        where p.prosrc like '%40001%' and n.nspname || '.' || p.proname not in ('private.execute_retention_job', 'private.need_publication_context', 'private.platform_price_add_version', 'private.worker_ai_patch', 'private.worker_ai_turn_recovery_v5', 'public.rpc_accept_ai_task_review', 'public.rpc_accept_reviewed_legal_bundle', 'public.rpc_activate_urgent', 'public.rpc_admit_account_lineage_service', 'public.rpc_apply_profile_avatar', 'public.rpc_authorize_data_export_download', 'public.rpc_begin_push_send', 'public.rpc_cancel_media_upload', 'public.rpc_cancel_worker_ai_turn', 'public.rpc_claim_ai_task_review_evaluation_service', 'public.rpc_claim_worker_ai_turn_service', 'public.rpc_clear_profile_avatar', 'public.rpc_close_remaining_search', 'public.rpc_complete_ai_task_review_evaluation_service', 'public.rpc_complete_data_export', 'public.rpc_complete_data_export_cleanup', 'public.rpc_complete_media_upload_service', 'public.rpc_complete_push_transport', 'public.rpc_complete_worker_ai_turn_service', 'public.rpc_confirm_need_edit', 'public.rpc_confirm_need_edit_from_review', 'public.rpc_dispatch_media_upload_service', 'public.rpc_fail_data_export', 'public.rpc_fail_media_upload_service', 'public.rpc_patch_worker_ai', 'public.rpc_prepare_account_closure', 'public.rpc_prepare_ai_task_review', 'public.rpc_prepare_worker_ai_review', 'public.rpc_publish_accepted_ai_task_review', 'public.rpc_publish_need_canonical', 'public.rpc_record_need_publication_decision_service', 'public.rpc_renew_data_export_lease', 'public.rpc_resolve_stale_response_after_need_edit', 'public.rpc_rotate_push_device_owned', 'public.rpc_save_need_location_review', 'public.rpc_save_requester_profile', 'public.rpc_save_worker_ai_review', 'public.rpc_save_worker_availability', 'public.rpc_save_worker_capacity', 'public.rpc_save_worker_location', 'public.rpc_send_agreement_message_v2', 'public.rpc_set_account_block', 'public.rpc_set_notification_preferences', 'public.rpc_set_push_device', 'public.rpc_set_push_device_owned', 'public.rpc_set_retention_hold', 'public.rpc_settle_media_upload_service', 'public.rpc_stage_media_upload_service', 'public.rpc_write_agreement_current_location', 'private.agreement_photo_context_v5', 'private.closure_assert_current_v5', 'private.closure_erasure_assert_current_v5', 'private.support_reference_v5', 'public.rpc_agreement_photo_upload_service_v5', 'public.rpc_claim_account_closure_action_service', 'public.rpc_complete_account_closure_action_service', 'public.rpc_dispatch_account_closure_action_service', 'public.rpc_finalize_account_closure_service', 'public.rpc_redact_account_closure_step_service', 'public.rpc_send_agreement_photo_message_v5', 'public.rpc_start_account_closure_execution', 'public.rpc_support_set_operator_service_v5', 'public.rpc_support_submit_v5')) then
    raise exception 'B24_UNCLASSIFIED_40001_SITE' using errcode = '55000';
  end if;
  for r in select * from b24_targets order by fn loop
    select count(*) into v_n from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname || '.' || p.proname = r.fn;
    if v_n <> 1 then raise exception 'B24_FUNCTION_NOT_UNIQUE: % (% found)', r.fn, v_n using errcode = '55000'; end if;
    select p.oid, p.prosrc into v_oid, v_src from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname || '.' || p.proname = r.fn;
    if position('PT409' in v_src) > 0 then raise exception 'B24_ALREADY_APPLIED: %', r.fn using errcode = '55000'; end if;
    v_n := (length(v_src) - length(replace(v_src, '''40001''', ''))) / 7;
    if v_n <> r.sites or position('40001' in replace(v_src, '''40001''', '')) > 0 then
      raise exception 'B24_SITE_COUNT_DRIFT: % expected % quoted sites, found %', r.fn, r.sites, v_n using errcode = '55000';
    end if;
    if v_strict and md5(v_src) is distinct from r.pre_md5 then raise exception 'B24_PREIMAGE_DRIFT: %', r.fn using errcode = '55000'; end if;
    insert into b24_before(fn, fn_oid, pre_src, attrs_md5) values (r.fn, v_oid, v_src, pg_temp.b24_attrs(v_oid));
  end loop;
end
$pre$;

do $convert$
declare r record; v_def text; v_new text;
begin
  for r in select fn, fn_oid from b24_before order by fn loop
    v_def := pg_get_functiondef(r.fn_oid);
    v_new := replace(v_def, '''40001''', '''PT409''');
    if v_new = v_def then raise exception 'B24_NOTHING_TO_CONVERT: %', r.fn; end if;
    execute v_new;
  end loop;
end
$convert$;

do $post$
declare r record; v_src text; v_n integer; v_certified text;
  v_strict boolean := coalesce(nullif(current_setting('b24.preimage', true), ''), 'strict') <> 'relaxed';
begin
  for r in select t.fn, t.sites, b.fn_oid, b.pre_src, b.attrs_md5 from b24_targets t join b24_before b using (fn) order by t.fn loop
    select prosrc into strict v_src from pg_proc where oid = r.fn_oid;
    if position('40001' in v_src) > 0 then raise exception 'B24_40001_LEFT: %', r.fn; end if;
    v_n := (length(v_src) - length(replace(v_src, '''PT409''', ''))) / 7;
    if v_n <> r.sites then raise exception 'B24_SITE_COUNT_AFTER: % expected %, found %', r.fn, r.sites, v_n; end if;
    if replace(v_src, '''PT409''', '''40001''') is distinct from r.pre_src then raise exception 'B24_CHANGE_BEYOND_THE_CODE: %', r.fn; end if;
    if pg_temp.b24_attrs(r.fn_oid) is distinct from r.attrs_md5 then raise exception 'B24_ATTRIBUTES_CHANGED: %', r.fn; end if;
  end loop;
  select certified into strict v_certified from b24_cert;
  if private.closure_source_digest_v5() is distinct from v_certified
     or v_certified is distinct from (select sha256 from private.closure_source_v5 where singleton)
     or v_certified is distinct from (select sha256 from private.closure_erasure_source_v5 where singleton)
     or not private.retention_ai_source_ready() then
    raise exception 'B24_CERTIFICATE_MOVED' using errcode = '55000';
  end if;
  if v_strict and exists (
       select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
        where p.prosrc like '%40001%' and n.nspname || '.' || p.proname not in ('private.agreement_photo_context_v5', 'private.closure_assert_current_v5', 'private.closure_erasure_assert_current_v5', 'private.support_reference_v5', 'public.rpc_agreement_photo_upload_service_v5', 'public.rpc_claim_account_closure_action_service', 'public.rpc_complete_account_closure_action_service', 'public.rpc_dispatch_account_closure_action_service', 'public.rpc_finalize_account_closure_service', 'public.rpc_redact_account_closure_step_service', 'public.rpc_send_agreement_photo_message_v5', 'public.rpc_start_account_closure_execution', 'public.rpc_support_set_operator_service_v5', 'public.rpc_support_submit_v5')) then
    raise exception 'B24_OTHER_40001_SITES_REMAIN' using errcode = '55000';
  end if;
end
$post$;

drop function pg_temp.b24_attrs(oid);
commit;
